using System;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
namespace PZ3D {
 static class CoreFinalRegressionTests {
  public static int Main(string[] args){try{CoreFixture.Initialize();if(args.Length==0||args[0]=="metadata")Metadata();if(args.Length==0||args[0]=="outcome")Outcome();if(args.Length==0)RecoveryAuthority();Console.WriteLine("FINAL REGRESSIONS: "+CoreFixture.Passed+" PASS");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
  static void RecoveryAuthority(){string root=CoreFixture.Root();var files=new System.Collections.Generic.Dictionary<string,byte[]>{{"橙子启动器.exe",CoreFixture.Bytes("launcher")},{"橙子更新助手.exe",CoreFixture.Bytes("owned-helper")},{"Web/app.js",CoreFixture.Bytes("old-js")}};CoreDeployment.Install(root,CoreFixture.Manifest("1.1.0",files),files,CoreFixture.Key);var next=new System.Collections.Generic.Dictionary<string,byte[]>(files);next["Web/app.js"]=CoreFixture.Bytes("new-js");string task=CoreUpdateTransaction.Stage(root,CoreFixture.Manifest("1.1.1",next),CoreFixture.Changed(),CoreFixture.Key),source;var helper=CoreUpdateTransaction.RecoveryHelper(root,task,CoreFixture.Key,out source);CoreFixture.Check(helper.sha256==CoreReleaseProtocol.Hash(files["橙子更新助手.exe"]),"recovery selects exact signed baseline helper");File.WriteAllText(source,"untrusted executable");CoreFixture.Reject(()=>CoreUpdateTransaction.RecoveryHelper(root,task,CoreFixture.Key,out source),"changed recovery helper cannot execute");File.WriteAllBytes(source,files["橙子更新助手.exe"]);string manifest=CoreDeployment.Safe(root,CoreDeployment.Tasks+"/"+task+"/manifest.sig");File.WriteAllBytes(manifest,new byte[256]);CoreFixture.Reject(()=>CoreUpdateTransaction.RecoveryHelper(root,task,CoreFixture.Key,out source),"untrusted target cannot authorize recovery handoff");CoreFixture.Reject(()=>CoreUpdateTransaction.History(root,CoreFixture.Key),"untrusted transaction cannot enter user-visible history");}
  static void Metadata(){string root=CoreFixture.Root();Directory.CreateDirectory(root);string rel="metadata.json",path=Path.Combine(root,rel);byte[] before=CoreFixture.Bytes(new string('a',65536)),after=CoreFixture.Bytes(new string('b',65536));File.WriteAllBytes(path,before);
   using(var entered=new ManualResetEventSlim()){var lockTask=Task.Run(()=>{using(var held=new FileStream(path,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){entered.Set();Thread.Sleep(150);}});entered.Wait();var snapshot=CoreDeployment.ReadBytes(path,65536);lockTask.Wait();CoreFixture.Check(snapshot.SequenceEqual(before),"bounded sharing retry returns exact snapshot");}
   using(var entered=new ManualResetEventSlim()){var lockTask=Task.Run(()=>{using(var held=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read)){entered.Set();Thread.Sleep(150);}});entered.Wait();CoreDeployment.Atomic(root,rel,after);lockTask.Wait();CoreFixture.Check(CoreDeployment.ReadBytes(path,65536).SequenceEqual(after),"publication survives temporary delete sharing denial");}
   var writer=Task.Run(()=>{for(int i=0;i<100;i++)CoreDeployment.Atomic(root,rel,i%2==0?before:after);});for(int i=0;i<200;i++){var bytes=CoreDeployment.ReadBytes(path,65536);CoreFixture.Check(bytes.SequenceEqual(before)||bytes.SequenceEqual(after),"concurrent snapshots contain one complete generation");}writer.Wait();CoreFixture.Reject(()=>CoreDeployment.ReadBytes(path,10),"size violations are not retry success");
   string installed=CoreFixture.Install(),task=CoreUpdateTransaction.Stage(installed,CoreFixture.Manifest("1.1.1",CoreFixture.B()),CoreFixture.Changed(),CoreFixture.Key),journal=CoreDeployment.Tasks+"/"+task+"/journal.json";byte[] raw=File.ReadAllBytes(CoreDeployment.Safe(installed,journal));writer=Task.Run(()=>{for(int i=0;i<50;i++)CoreDeployment.Atomic(installed,journal,raw);});for(int i=0;i<50;i++)CoreFixture.Check(CoreUpdateTransaction.GetTaskInfo(installed,task,CoreFixture.Key).State=="Staged","authenticated GetTaskInfo survives concurrent journal publication");writer.Wait();
   using(var held=new FileStream(path,FileMode.Open,FileAccess.ReadWrite,FileShare.None))CoreFixture.Reject(()=>CoreDeployment.ReadBytes(path,65536),"persistent sharing lock fails within retry bound");
  }
  static void Outcome(){foreach(bool healthy in new[]{true,false}){string root=CoreFixture.Install();string task=CoreUpdateTransaction.Stage(root,CoreFixture.Manifest("1.1.1",CoreFixture.B()),CoreFixture.Changed(),CoreFixture.Key);try{CoreUpdateTransaction.Apply(root,task,p=>healthy,null,CoreFixture.Key);}catch(CoreUpdateException){}using(var service=new CoreUpdateService(root,CoreFixture.Key,t=>null,(u,t)=>null)){var s=service.Status();CoreFixture.Check(s.state==(healthy?"Succeeded":"RolledBack"),"restart restores durable "+(healthy?"success":"rollback"));CoreFixture.Check(healthy||s.message.Contains("confirm healthy"),"rollback preserves actual failure reason");CoreFixture.Check(s.history.Count==1&&s.history[0].TaskId==task,"independent update status exposes durable task history");}}
   string interrupted=CoreFixture.Install();CoreUpdateTransaction.Stage(interrupted,CoreFixture.Manifest("1.1.1",CoreFixture.B()),CoreFixture.Changed(),CoreFixture.Key);CoreUpdateTransaction.Recover(interrupted,CoreFixture.Key);using(var service=new CoreUpdateService(interrupted,CoreFixture.Key,t=>null,(u,t)=>null))CoreFixture.Check(service.Status().history[0].Message.Contains("interrupted"),"ordinary recovery retains interruption reason");
   string pending=CoreFixture.Install(),id=CoreUpdateTransaction.Stage(pending,CoreFixture.Manifest("1.1.1",CoreFixture.B()),CoreFixture.Changed(),CoreFixture.Key);CoreUpdateService candidate=null;using(var committed=new ManualResetEventSlim())try{CoreUpdateTransaction.Apply(pending,id,p=>{candidate=new CoreUpdateService(pending,CoreFixture.Key,t=>null,(u,t)=>null);CoreFixture.Check(candidate.Status().state=="PendingHealth","candidate initially exposes pending health");candidate.Progress=s=>{if(s.state=="Succeeded")committed.Set();};return true;},null,CoreFixture.Key);CoreFixture.Check(committed.Wait(3000),"health commit reaches existing UI without another request");}finally{if(candidate!=null)candidate.Dispose();}}
 }
}
